OPJ_BOOL write_jpeg2000_tile_parts(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                                   OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                                   struct opj_event_mgr *p_manager)
{
    OPJ_UINT32 current_tile_part = 0;
    OPJ_BOOL success = OPJ_TRUE;
    OPJ_UINT32 tile_number = 0;
    OPJ_UINT32 tile_parts = 0;
    OPJ_UINT32 tile_data_size = 0;
    OPJ_BYTE *tile_data = NULL;

    if (!p_j2k || !p_data || !p_data_written || !p_stream) {
        return OPJ_FALSE;
    }

    tile_number = p_j2k->current_tile_number;
    tile_parts = p_j2k->cinfo->tile_part_info[tile_number].number_of_parts;

    while (current_tile_part < tile_parts && success) {
        tile_data = p_j2k->cinfo->tile_part_info[tile_number].data + current_tile_part;
        tile_data_size = p_j2k->cinfo->tile_part_info[tile_number].length[current_tile_part];

        if (tile_data_size > p_total_data_size - *p_data_written) {
            tile_data_size = p_total_data_size - *p_data_written;
            success = OPJ_FALSE;
        }

        if (!opj_write_sot_marker(p_stream, tile_number + 1, current_tile_part + 1,
                                  tile_data_size, p_manager)) {
            success = OPJ_FALSE;
        }

        if (!opj_stream_write_data(p_stream, tile_data, tile_data_size, p_manager)) {
            success = OPJ_FALSE;
        }

        *p_data_written += tile_data_size;

        if (!opj_write_sod_marker(p_stream, p_manager)) {
            success = OPJ_FALSE;
        }

        current_tile_part++;
    }

    return success;
}

OPJ_BOOL write_jpeg2000_tile_parts(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                                   OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                                   struct opj_event_mgr *p_manager) {
    OPJ_UINT32 written = 0;
    OPJ_UINT32 tile_part = 0;
    OPJ_BOOL result = OPJ_TRUE;

    if (!p_j2k || !p_data || !p_data_written || !p_stream) {
        return OPJ_FALSE;
    }

    while (written < p_total_data_size && result) {
        /* Write Start Of Tile (SOT) marker */
        if (!j2k_write_sot(p_j2k, tile_part, p_stream, p_manager)) {
            result = OPJ_FALSE;
            break;
        }

        /* Calculate size of current tile part */
        OPJ_UINT32 tile_part_size = p_total_data_size - written;

        if (tile_part_size > 0) {
            if (!opj_stream_write_data(p_stream, p_data + written, tile_part_size, p_manager)) {
                result = OPJ_FALSE;
                break;
            }
            written += tile_part_size;
            *p_data_written = written;
        }

        /* Write End Of Data (SOD) marker */
        if (!j2k_write_sod(p_stream, p_manager)) {
            result = OPJ_FALSE;
            break;
        }

        tile_part++;
    }

    /* Cinema format handling if needed */
    if (p_j2k->cinema && tile_part > 0) {
        /* Perform cinema-specific operations */
        if (!handle_cinema_tile_parts(p_j2k, p_stream, p_manager)) {
            result = OPJ_FALSE;
        }
    }

    return result;
}

OPJ_BOOL write_jpeg2000_tile_parts(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written, OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream, struct opj_event_mgr *p_manager) {
    OPJ_UINT32 tile_idx = 0;
    OPJ_UINT32 tp_num = 0;
    OPJ_UINT32 num_tile_parts = 0;
    OPJ_UINT32 bytes_written = 0;
    OPJ_BOOL success = OPJ_TRUE;

    for (tile_idx = 0; tile_idx < p_j2k->num_tiles; ++tile_idx) {
        num_tile_parts = p_j2k->tile[tile_idx].num_tile_parts;

        for (tp_num = 0; tp_num < num_tile_parts; ++tp_num) {
            OPJ_UINT32 sot_size = 0;
            OPJ_UINT32 sod_size = 0;

            /* Write SOT marker */
            if (!opj_j2k_write_sot(p_j2k, tile_idx, tp_num, p_stream, p_manager)) {
                success = OPJ_FALSE;
                break;
            }

            sot_size = 11; /* SOT marker (2 bytes) + Length (2 bytes) + Tile number (2 bytes) + Tile part number (2 bytes) + TLB (3 bytes) */
            bytes_written += sot_size;

            if (bytes_written >= p_total_data_size) {
                success = OPJ_FALSE;
                break;
            }

            /* Write SOD marker */
            if (!opj_j2k_write_sod(p_j2k, p_stream, p_manager)) {
                success = OPJ_FALSE;
                break;
            }

            sod_size = 1; /* SOD marker is just 1 byte */
            bytes_written += sod_size;

            if (bytes_written >= p_total_data_size) {
                success = OPJ_FALSE;
                break;
            }

            /* Write tile data */
            OPJ_UINT32 tile_data_size = p_j2k->tile[tile_idx].tile_part_size[tp_num];
            OPJ_UINT32 copy_size = (tile_data_size < (p_total_data_size - bytes_written)) ? tile_data_size : (p_total_data_size - bytes_written);

            if (!opj_stream_write(p_stream, p_data + bytes_written, copy_size)) {
                success = OPJ_FALSE;
                break;
            }

            bytes_written += copy_size;

            if (bytes_written >= p_total_data_size) {
                success = OPJ_FALSE;
                break;
            }
        }

        if (!success) {
            break;
        }
    }

    *p_data_written = bytes_written;

    return success;
}

OPJ_BOOL write_jpeg2000_tile_parts(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                                   OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                                   struct opj_event_mgr *p_manager) {
    OPJ_UINT32 tile_index, tile_part_index;
    OPJ_UINT32 total_tile_parts = 0;
    OPJ_BOOL result = OPJ_TRUE;
    OPJ_BYTE *current_data = p_data;
    OPJ_UINT32 bytes_remaining = p_total_data_size;
    OPJ_UINT32 bytes_written = 0;

    for (tile_index = 0; tile_index < p_j2k->cinfo->numresolution; ++tile_index) {
        total_tile_parts = p_j2k->cinfo->tile[tile_index].num_tile_parts;
        for (tile_part_index = 0; tile_part_index < total_tile_parts; ++tile_part_index) {
            OPJ_UINT32 tile_part_data_size = p_j2k->cinfo->tile[tile_index].tile_part_data_size[tile_part_index];

            if (bytes_remaining < tile_part_data_size) {
                result = OPJ_FALSE;
                break;
            }

            /* Write SOT marker if applicable */
            if (tile_part_index == 0) {
                opj_j2k_write_SOT(p_stream, tile_index, p_j2k->cinfo->tile[tile_index].data_length);
            }

            /* Write SOD marker */
            opj_j2k_write_SOD(p_stream);

            /* Write tile part data */
            if (!opj_stream_write(p_stream, current_data, tile_part_data_size)) {
                result = OPJ_FALSE;
                break;
            }

            bytes_written += tile_part_data_size;
            current_data += tile_part_data_size;
            bytes_remaining -= tile_part_data_size;

            /* Write EOD marker if last tile part */
            if (tile_part_index == total_tile_parts - 1) {
                opj_j2k_write_EOD(p_stream);
            }

            /* Handle cinema format if applicable */
            if (p_j2k->cinema_mode) {
                opj_j2k_handle_cinema_format(p_j2k, p_stream, p_manager);
            }
        }

        if (!result) {
            break;
        }
    }

    *p_data_written = bytes_written;
    return result;
}

OPJ_BOOL write_jpeg2000_tile_parts(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written, OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream, struct opj_event_mgr *p_manager) {
    OPJ_UINT32 tile_idx;
    OPJ_UINT32 tile_part_idx;
    OPJ_UINT32 tile_parts;
    OPJ_BOOL result = OPJ_TRUE;
    OPJ_UINT32 bytes_written = 0;

    if (!p_j2k || !p_data || !p_data_written || !p_stream || !p_manager) {
        return OPJ_FALSE;
    }

    tile_parts = p_j2k->cinfo->tile_parts;
    for (tile_idx = 0; tile_idx < p_j2k->cinfo->numresolution; ++tile_idx) {
        for (tile_part_idx = 0; tile_part_idx < tile_parts; ++tile_part_idx) {
            OPJ_BYTE *tile_data = p_data + bytes_written;
            OPJ_UINT32 tile_data_size = p_total_data_size - bytes_written;

            if (!tile_data || tile_data_size <= 0) {
                result = OPJ_FALSE;
                break;
            }

            /* Write SOT marker if applicable */
            if (tile_part_idx == 0) {
                if (!opj_j2k_write_sot(p_j2k, p_stream, p_manager)) {
                    result = OPJ_FALSE;
                    break;
                }
            }

            /* Write tile data */
            if (!opj_stream_write_data(p_stream, tile_data, tile_data_size, p_manager)) {
                result = OPJ_FALSE;
                break;
            }

            bytes_written += tile_data_size;

            /* Write SOD marker if applicable */
            if (tile_part_idx < tile_parts - 1) {
                if (!opj_j2k_write_sod(p_j2k, p_stream, p_manager)) {
                    result = OPJ_FALSE;
                    break;
                }
            }
        }

        if (!result) {
            break;
        }
    }

    *p_data_written = bytes_written;
    return result;
}
